#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int ans = 0, i = 0, j = 0, n = 0, x = 0;
    // 两个序列都是 1..n 的排列，每个值的位置唯一，允许子序列跳过元素。
    n = read();
    for (i = 0; i < n; i += 1)  {
        a[i] = read();
    }
    for (i = 0; i < n; i += 1)  {
        x = read();
        // b[value] 记录该值在第二排列的零起点位置。
        b[x] = i;
    }
    ans = 0;
    for (i = 0; i < n; i += 1)  {
        d[i] = 1;
        for (j = 0; j < i; j += 1)  {
            // 第一排列中 j 在前，第二排列位置也必须在前，才能接续 d[j]+1。
            if (b[a[j]] < b[a[i]])  {
                d[i] = mx(d[i], (d[j] + 1));
            }
        }
        ans = mx(ans, d[i]);
    }
    // 最长方案可能在任意位置结束，输出所有 d[i] 的最大值。
    emit(ans);
    return 0;
}

