use std::io:: {
    self, Read
}
;
fn mn(a: i32, b: i32) -> i32  {
    a.min(b)
}
fn mx(a: i32, b: i32) -> i32  {
    a.max(b)
}
fn emit(x: i32)  {
    print!("{} ", x);
}
fn emitstr(a: &Vec<i32>, n: i32)  {
    if n == 0  {
        print!("-");
    }
    for i in 0..n  {
        print!("{}", a[i as usize] as u8 as char);
    }
    print!(" ");
}
struct Reader  {
    t: Vec<String>,
    p: usize,
}
impl Reader  {
    fn new() -> Self  {
        let mut s = String::new();
        io::stdin().read_to_string(&mut s).unwrap();
        Self  {
            t: s.split_whitespace().map(String::from).collect(),
            p: 0,
        }
    }
    fn read(&mut self) -> i32  {
        let x = self.t[self.p].parse().unwrap();
        self.p += 1;
        x
    }
    fn readstr(&mut self, a: &mut Vec<i32>) -> i32  {
        let s = &self.t[self.p];
        self.p += 1;
        if s == "-"  {
            return 0;
        }
        for (i, c) in s.bytes().enumerate()  {
            a[i] = c as i32;
        }
        s.len() as i32
    }
}
fn main()  {
    let mut reader = Reader::new();
    let mut a = vec![0i32;
    20000];
    let mut b = vec![0i32;
    20000];
    let mut d = vec![0i32;
    20000];
    let mut e = vec![0i32;
    20000];
    let mut ans: i32 = 0;
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut n: i32 = 0;
    let mut x: i32 = 0;
    // 两个序列都是 1..n 的排列，每个值的位置唯一，允许子序列跳过元素。
    n = reader.read();
    i = 0;
    while i < n  {
        a[(i) as usize] = reader.read();
        i += 1;
    }
    i = 0;
    while i < n  {
        x = reader.read();
        // b[value] 记录该值在第二排列的零起点位置。
        b[(x) as usize] = i;
        i += 1;
    }
    ans = 0;
    i = 0;
    while i < n  {
        d[(i) as usize] = 1;
        j = 0;
        while j < i  {
            // 第一排列中 j 在前，第二排列位置也必须在前，才能接续 d[j]+1。
            if (b[(a[(j) as usize]) as usize] < b[(a[(i) as usize]) as usize])  {
                d[(i) as usize] = mx(d[(i) as usize], (d[(j) as usize] + 1));
            }
            j += 1;
        }
        ans = mx(ans, d[(i) as usize]);
        i += 1;
    }
    // 最长方案可能在任意位置结束，输出所有 d[i] 的最大值。
    emit(ans);
}
